import unicodedata

def slugify(s):
    s = s.lower()
    # Normalize to NFKD form which separates base characters from diacritics
    s = unicodedata.normalize('NFKD', s)
    # Remove combining diacritical marks
    s = ''.join(c for c in s if not unicodedata.combining(c))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    # Collapse multiple dashes
    result = []
    prev = None
    for ch in result + out:
        if ch == '-' and prev == '-':
            continue
        result.append(ch)
        prev = ch
    # Strip leading/trailing dashes
    return ''.join(result).strip('-')

import unicodedata

def slugify(s):
    s = s.lower()
    # Normalize Unicode to decompose characters like 'õ' into 'o' + combining mark
    s = unicodedata.normalize('NFKD', s)
    # Remove combining characters (accents, etc.)
    s = ''.join(c for c in s if not unicodedata.combining(c))

    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            # Treat any non-alphanumeric character as a separator
            # Only add '-' if the last character in out is not already '-'
            if out and out[-1] != '-':
                out.append('-')
    # Remove trailing '-' if present
    if out and out[-1] == '-':
        out.pop()
    return ''.join(out)

